def dedupe_extension(name):
    parts = name.split(".")
    if len(parts) >= 3 and parts[-1] == parts[-2] and parts[-1] != "":
        return ".".join(parts[:-1])
    return name

def is_two_strings_isomorphic(a, b):
    if len(a) != len(b):
        return False
    map_ab, map_ba = {}, {}
    for x, y in zip(a, b):
        if x in map_ab and map_ab[x] != y:
            return False
        if y in map_ba and map_ba[y] != x:
            return False
        map_ab[x] = y
        map_ba[y] = x
    return True

def sanitize_filename_lower(name):
    lowered = name.lower().replace(" ", "-")
    allowed = set("abcdefghijklmnopqrstuvwxyz0123456789-.")
    return "".join(c for c in lowered if c in allowed)

def sort_by_distance_from_mean(nums):
    mean = sum(nums) / len(nums)
    return sorted(nums, key=lambda x: (abs(x - mean), x))

def reorder_by_inverse_permutation(items, perm):
    result = [None] * len(items)
    for i, p in enumerate(perm):
        result[p] = items[i]
    return result

def replace_vowels_with_symbol(s, symbol):
    vowels = set("aeiouAEIOU")
    return "".join(symbol if c in vowels else c for c in s)

def zeckendorf_length(n):
    if n == 0:
        return 0
    fibs = [1, 2]
    while fibs[-1] <= n:
        fibs.append(fibs[-1] + fibs[-2])
    fibs.pop()
    count = 0
    remaining = n
    for f in reversed(fibs):
        if f <= remaining:
            remaining -= f
            count += 1
    return count

