def mode_length_weighted(word_counts):
    length_totals = {}
    for word, cnt in word_counts.items():
        length_totals[len(word)] = length_totals.get(len(word), 0) + cnt
    best = sorted(length_totals.items(), key=lambda kv: (-kv[1], kv[0]))[0]
    return best[0]

def nearest_business_day(day_num, weekend_days):
    d = day_num
    while d % 7 in weekend_days:
        d += 1
    return d

def count_goldbach_pairs(n):
    def is_prime(x):
        if x < 2:
            return False
        if x < 4:
            return True
        if x % 2 == 0:
            return False
        i = 3
        while i * i <= x:
            if x % i == 0:
                return False
            i += 2
        return True
    count = 0
    for p in range(2, n // 2 + 1):
        if is_prime(p) and is_prime(n - p):
            count += 1
    return count

def count_polite_representations(n):
    count_odd_divisors = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i % 2 == 1:
                count_odd_divisors += 1
            j = n // i
            if j != i and j % 2 == 1:
                count_odd_divisors += 1
        i += 1
    return count_odd_divisors - 1

def is_semiprime(n):
    if n < 4:
        return False
    count = 0
    temp = n
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            temp //= d
            count += 1
            if count > 2:
                return False
        d += 1
    if temp > 1:
        count += 1
    return count == 2

def combine_rankings_borda_count(list1, list2):
    n1, n2 = len(list1), len(list2)
    points1 = {v: n1 - 1 - i for i, v in enumerate(list1)}
    points2 = {v: n2 - 1 - i for i, v in enumerate(list2)}
    items = set(list1) | set(list2)
    def total(x):
        return points1.get(x, 0) + points2.get(x, 0)
    return sorted(items, key=lambda x: (-total(x), x))

def first_and_last_weekday_of_month(year, month, weekday_num):
    def is_leap(y):
        return y % 4 == 0 and (y % 100 != 0 or y % 400 == 0)
    def wd(y, m, d):
        if m < 3:
            m += 12
            y -= 1
        K = y % 100
        J = y // 100
        h = (d + (13 * (m + 1)) // 5 + K + K // 4 + J // 4 + 5 * J) % 7
        return (h + 5) % 7
    dim = [31, 29 if is_leap(year) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1]
    first_wd = wd(year, month, 1)
    offset = (weekday_num - first_wd) % 7
    first_day = 1 + offset
    last_wd = wd(year, month, dim)
    diff = (last_wd - weekday_num) % 7
    last_day = dim - diff
    return (first_day, last_day)

def value_span(d):
    if not d:
        return 0
    vals = list(d.values())
    return max(vals) - min(vals)

def bottom_k_names_by_score(records, k):
    ordered = sorted(records, key=lambda r: (r[1], r[0]))
    return [r[0] for r in ordered[:k]]

def dict_diff_labels(old, new):
    result = {}
    for k in old:
        if k in new:
            if new[k] > old[k]:
                result[k] = "increased"
            elif new[k] < old[k]:
                result[k] = "decreased"
            else:
                result[k] = "same"
    return result

def max_gap_between_elements(lst):
    if len(lst) < 2:
        return 0
    s = sorted(lst)
    return max(s[i + 1] - s[i] for i in range(len(s) - 1))

def is_arithmetic_sequence(lst):
    if len(lst) <= 2:
        return True
    diff = lst[1] - lst[0]
    for i in range(2, len(lst)):
        if lst[i] - lst[i - 1] != diff:
            return False
    return True

def convert_spaces_to_underscores(s):
    import re
    return re.sub(r'\s+', '_', s.strip())

def is_valid_hex_color_short(s):
    if len(s) != 4 or s[0] != '#':
        return False
    hexdigits = set('0123456789abcdefABCDEF')
    return all(c in hexdigits for c in s[1:])

def second_highest_value(d):
    distinct = sorted(set(d.values()), reverse=True)
    if len(distinct) < 2:
        return None
    return distinct[1]

def weighted_score_rank(records):
    def avg(scores):
        return sum(scores) / len(scores)
    return [r[0] for r in sorted(records, key=lambda r: (-avg(r[1]), r[0]))]
